import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Tech Talk: Going NATS","description":"","frontmatter":{"title":"Ceph Tech Talk: Going NATS","date":"2021-08-26T00:00:00.000Z","updated":"2021-08-27T00:00:00.000Z","tags":["Ceph","Lua scripting","NATS","Storage notifications","Open source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Tech_Talk_-_Going_NATS.md","filePath":"posts/2021/Ceph_Tech_Talk_-_Going_NATS.md","lastUpdated":1780459816000}'),p={name:"posts/2021/Ceph_Tech_Talk_-_Going_NATS.md"};function l(n,t,s,r,_,T){return i(),a("div",null,[...t[0]||(t[0]=[o("<p>Ceph Tech Talk: Going NATS会议纪要：</p><p>本次技术会谈的主题是使用Lua脚本与NATS Blue客户端集成，以实现Ceph存储桶的通知功能。</p><p><strong>会议内容概述</strong>：</p><ol><li><p><strong>背景介绍</strong>：Martin Brisman介绍了如何通过Lua脚本在Ceph中集成NATS Blue客户端，实现存储桶通知功能。存储桶通知可以在特定事件（如添加或删除对象）发生时，向外部系统发送通知。</p></li><li><p><strong>应用场景</strong>：展示了数据管道的示例，其中上传的X光照片在Ceph存储桶中触发通知，通过Knative事件组件处理，评估疾病风险，并将结果返回给诊所或研究人员。</p></li><li><p><strong>技术细节</strong>：目前Ceph支持向Kafka、AMQP和HTTP端点发送通知，但希望通过Lua脚本集成NATS，而无需修改源代码。Lua脚本可以在Ceph中上传，并在每次收到存储桶请求时执行。</p></li><li><p><strong>演示环节</strong>：Martin展示了如何上传Lua脚本到Ceph，并使用rgw admin命令安装所需的Lua包。通过s3cmd命令向存储桶发送请求，演示了Lua脚本如何捕获请求并将其发送到NATS服务器。</p></li><li><p><strong>未来展望</strong>：讨论了Lua脚本的潜在集成机会，如与Elasticsearch和Prometheus的集成。提到了正在开发中的背景脚本，这将有助于监控和在请求之间保存缓存。</p></li><li><p><strong>问题与讨论</strong>：讨论了Lua脚本的优势，如无需修改源代码即可集成新系统，以及其简单易用的特点。也提到了一些限制，如无法在运行之间缓存数据，以及需要改进的地方，如背景数据结构的持久化。</p></li></ol><p><strong>会议决定</strong>：</p><ul><li>鼓励社区成员尝试使用Lua脚本进行集成和调试，并提供反馈以指导未来功能的开发。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续开发背景脚本和数据结构，以支持更复杂的监控和集成需求。</li><li>收集社区反馈，优化Lua脚本功能。</li></ul><p><strong>标签</strong>：</p><ul><li>Ceph</li><li>Lua scripting</li><li>NATS</li><li>Storage notifications</li><li>Open source</li></ul>",10)])])}const c=e(p,[["render",l]]);export{u as __pageData,c as default};
